<script setup>
import { onMounted, reactive, ref } from 'vue'
import request from '../api/request'
const addresses=ref([]), messages=ref([]), points=ref(null), records=ref([]), notice=ref(''), feedback=reactive({title:'',content:''})
const address=reactive({receiverName:'',receiverPhone:'',province:'',city:'',district:'',detailAddress:'',isDefault:false})
function show(v){notice.value=v;setTimeout(()=>notice.value='',2500)}
async function load(){const [a,m,p,r]=await Promise.all([request.get('/addresses'),request.get('/messages'),request.get('/points/account'),request.get('/points/records')]);addresses.value=a.data.data||[];messages.value=m.data.data||[];points.value=p.data.data;records.value=r.data.data||[]}
async function addAddress(){await request.post('/addresses',address);Object.keys(address).forEach(k=>address[k]=k==='isDefault'?false:'');show('地址保存成功');await load()}
async function removeAddress(id){await request.delete(`/addresses/${id}`);show('地址已删除');await load()}
async function setDefault(id){await request.put(`/addresses/${id}/default`);show('默认地址已设置');await load()}
async function readMessage(id){await request.put(`/messages/${id}/read`);await load()}
async function sendFeedback(){await request.post('/messages/feedback',feedback);feedback.title='';feedback.content='';show('客服留言已提交');await load()}
onMounted(load)
</script>
<template><main class="page-shell feature-page"><header class="page-heading"><div><div class="section-kicker">SERVICE CENTER</div><h1>地址、消息与会员中心</h1><p>管理收货地址，查看通知，联系平台客服并查询积分。</p></div></header><p v-if="notice" class="notice success">{{notice}}</p><div class="feature-grid"><section class="user-center-card"><div class="card-title"><h2>收货地址</h2></div><form class="profile-form" @submit.prevent="addAddress"><input v-model="address.receiverName" required placeholder="收货人姓名"/><input v-model="address.receiverPhone" required placeholder="手机号"/><input v-model="address.province" required placeholder="省"/><input v-model="address.city" required placeholder="市"/><input v-model="address.district" required placeholder="区/县"/><input v-model="address.detailAddress" required placeholder="详细地址"/><label><input v-model="address.isDefault" type="checkbox"/> 设为默认地址</label><button class="primary-button">保存地址</button></form><article v-for="a in addresses" :key="a.id" class="feature-row"><div><strong>{{a.receiverName}} {{a.receiverPhone}}</strong><p>{{a.province}}{{a.city}}{{a.district}}{{a.detailAddress}}</p></div><div><button class="secondary-button" @click="setDefault(a.id)">{{a.isDefault?'默认地址':'设为默认'}}</button><button class="danger-button" @click="removeAddress(a.id)">删除</button></div></article></section><section class="user-center-card"><div class="card-title"><h2>会员积分</h2><strong class="points-number">{{points?.balance||0}} 分</strong></div><p>累计获得：{{points?.totalEarned||0}} 分；支付成功后按订单金额取整自动发放。</p><div v-for="r in records" :key="r.id" class="feature-row"><span>{{r.reason}}</span><strong :class="r.changeAmount>0?'points-add':'points-sub'">{{r.changeAmount>0?'+':''}}{{r.changeAmount}}</strong></div></section><section class="user-center-card"><div class="card-title"><h2>站内消息</h2></div><article v-for="m in messages" :key="m.id" class="feature-row" :class="{unread:!m.isRead}"><div><strong>{{m.title}}</strong><p>{{m.content}}</p><small>{{m.createTime}}</small></div><button v-if="!m.isRead" class="secondary-button" @click="readMessage(m.id)">标记已读</button></article><p v-if="!messages.length">暂无消息</p></section><section class="user-center-card"><div class="card-title"><h2>联系客服</h2></div><form class="profile-form" @submit.prevent="sendFeedback"><input v-model="feedback.title" required maxlength="100" placeholder="问题标题"/><textarea v-model="feedback.content" required maxlength="1000" placeholder="请描述你的问题"></textarea><button class="primary-button">提交留言</button></form></section></div></main></template>
